/**
 * Layout new button
 */
lD.addLayout = function () {
  lD.selectObject();
  lD.common.showLoadingScreen();
  $.ajax({
    type: urlsForApi.layout.add.type,
    url: urlsForApi.layout.add.url,
    cache: false,
    data: {
      folderId: lD.folderId
    },
    dataType: 'json',
    success: function (response, textStatus, error) {
      lD.common.hideLoadingScreen();
      if (response.success && response.id) {
        XiboRedirect(urlsForApi.layout.designer.url.replace(':id', response.id));
      } else {
        if (response.login) {
          LoginBox(response.message);
        } else {
          SystemMessage(response.message, false);
        }
      }
    },
    error: function (xhr, textStatus, errorThrown) {
      lD.common.hideLoadingScreen();
      SystemMessage(xhr.responseText, false);
    }
  });
};

